FUNCTION_BLOCK FB_AOD_TuyereDecarburization
(*
====================================================================================================
PROJECT:        Lumina Industrial Automation Suite - Advanced Metallurgical Solutions
MODULE:         FB_AOD_TuyereDecarburization
ARCHITECT:      Principal Automation Fellow & Cyber-Physical Systems Chair (V7 Max-Persona)
DOMAIN:         Heavy Metallurgy - Argon-Oxygen Decarburization (AOD) Refining Converter
SUBSYSTEM:      Submerged Bottom Tuyere Annular Gas Shrouding, 2oo3 TMR Sensory Voting,
                State-Space Luenberger/Kalman Observer, Dynamic Decarburization Kinetics,
                and Anti-Weeping Ferrostatic Safety Interlocks.
STANDARDS:      IEC 61131-3, IEC 61508 / IEC 61511 (SIL 2 Systematic Capability), NFPA 86D
====================================================================================================
DESCRIPTION:
  This function block governs the dynamic gas injection aerodynamics and metallurgical kinetics
  for a bottom-blown Argon-Oxygen Decarburization (AOD) converter refining stainless and high-alloy
  steels. The block coordinates:
    1. Triple Modular Redundant (2oo3) voting on pyrometric bath temperatures and core backpressures.
    2. Dynamic ferrostatic head calculation with high-speed anti-weeping safety purge logic.
    3. Stoichiometric off-gas mass balance tracking instantaneous carbon removal rate (dC/dt).
    4. 3-State discrete Luenberger/Kalman state-space observer estimating dissolved bath carbon [ppm],
       tuyere refractory tip temperature [deg C], and protective slag/metal accretion thickness [mm].
    5. Multi-stage metallurgical decarburization sequencing (Stages 1-4) with closed-loop dynamic
       annular gas shrouding (Q_shroud / Q_core) to protect doloma/magnesite-chromite refractory.
====================================================================================================
*)

VAR_INPUT
    bEnable                         : BOOL;     (* System operational enable master command [TRUE=Active] *)
    bEStop                          : BOOL;     (* Failsafe safety relay status [TRUE=Healthy/De-energized to trip] *)
    bVesselInVerticalBlow           : BOOL;     (* Vessel mechanical tilt angle interlock [TRUE=90 deg Vertical] *)
    bInertGasEmergencyAvailable     : BOOL;     (* High-pressure backup N2 accumulator system ready [TRUE=Ready] *)
    rMeltMass_ton                   : REAL;     (* Total liquid steel bath weight in converter [ton] (50.0..180.0) *)
    rBathTemp_degC_Ch1              : REAL;     (* Submerged tuyere optical pyrometer Channel 1 [deg C] (1400..1800) *)
    rBathTemp_degC_Ch2              : REAL;     (* Submerged tuyere optical pyrometer Channel 2 [deg C] (1400..1800) *)
    rBathTemp_degC_Ch3              : REAL;     (* Submerged tuyere optical pyrometer Channel 3 [deg C] (1400..1800) *)
    rCorePres_bar_PT1               : REAL;     (* Primary core gas manifold pressure sensor PT-101 [bar] (0.0..25.0) *)
    rCorePres_bar_PT2               : REAL;     (* Primary core gas manifold pressure sensor PT-102 [bar] (0.0..25.0) *)
    rCorePres_bar_PT3               : REAL;     (* Primary core gas manifold pressure sensor PT-103 [bar] (0.0..25.0) *)
    rOffGasCO_pct                   : REAL;     (* Fast mass-spectrometer / NDIR off-gas CO concentration [% vol] *)
    rOffGasCO2_pct                  : REAL;     (* Fast mass-spectrometer / NDIR off-gas CO2 concentration [% vol] *)
    rOffGasFlow_Nm3min              : REAL;     (* Total off-gas primary duct exhaust volumetric flow rate [Nm3/min] *)
    rBathCarbonInitial_ppm          : REAL;     (* Initial melt carbon concentration from optical emission spec [ppm] *)
    rCarbonTarget_ppm               : REAL;     (* Aim carbon concentration specification at tap [ppm] (e.g. 250 ppm) *)
    rTuyereShroudSupplyPres_bar     : REAL;     (* Annular shroud protective gas manifold supply pressure [bar] *)
    rCycleTime_s                    : REAL;     (* Deterministic PLC task cycle scan period [s] (e.g. 0.050 s) *)
    bAcknowledgeFault               : BOOL;     (* Operator fault reset push-button [Active High] *)
END_VAR

VAR_OUTPUT
    bSystemReady                    : BOOL;     (* Overall automation subsystem healthy and ready for blow *)
    wStatusWord                     : WORD;     (* Subsystem operational phase & status bitfield [HEX] *)
    wAlarmWord                      : WORD;     (* Diagnostic alarm, sensor fault & safety trip bitfield [HEX] *)
    rCoreOxygenFlowSP_Nm3min        : REAL;     (* Core nozzle dynamic oxygen mass-flow setpoint [Nm3/min] *)
    rCoreInertFlowSP_Nm3min         : REAL;     (* Core nozzle dynamic inert gas (Ar/N2) setpoint [Nm3/min] *)
    rShroudInertFlowSP_Nm3min       : REAL;     (* Annular shroud ring protective cooling gas setpoint [Nm3/min] *)
    rInstantDecarbRate_kgmin        : REAL;     (* Stoichiometric instantaneous bath carbon oxidation rate [kg/min] *)
    rEstBathCarbon_ppm              : REAL;     (* Luenberger observer filtered bath carbon concentration [ppm] *)
    rTuyereRefractoryWear_mm        : REAL;     (* Cumulative estimated tuyere refractory wall erosion [mm] *)
    bEmergencyPurgeActive           : BOOL;     (* High-pressure anti-weeping safety purge valve open command *)
    bTuyereOverheatAlarm            : BOOL;     (* Tuyere tip temperature threshold limit alarm flag *)
END_VAR

VAR
    (* Multi-stage Sequencer Control *)
    iBlowState                      : INT := 0; (* 0=STANDBY, 10=STAGE1, 20=STAGE2, 30=STAGE3, 40=REDUCTION, 90=EMERGENCY, 99=LOCKOUT *)

    (* 2oo3 TMR Voting Variables - Bath Temperature Pyrometers *)
    rVotedBathTemp_degC             : REAL;     (* Median voted bath temperature [deg C] *)
    bTempCh1_Fault                  : BOOL;     (* Pyrometer channel 1 signal discrepancy fault *)
    bTempCh2_Fault                  : BOOL;     (* Pyrometer channel 2 signal discrepancy fault *)
    bTempCh3_Fault                  : BOOL;     (* Pyrometer channel 3 signal discrepancy fault *)
    iTempFaultCount                 : INT;      (* Total number of faulted pyrometer channels *)

    (* 2oo3 TMR Voting Variables - Tuyere Core Pressure Transmitters *)
    rVotedCorePres_bar              : REAL;     (* Median voted core manifold gas pressure [bar] *)
    bPresPT1_Fault                  : BOOL;     (* Pressure transmitter 1 signal discrepancy fault *)
    bPresPT2_Fault                  : BOOL;     (* Pressure transmitter 2 signal discrepancy fault *)
    bPresPT3_Fault                  : BOOL;     (* Pressure transmitter 3 signal discrepancy fault *)
    iPresFaultCount                 : INT;      (* Total number of faulted pressure transmitters *)

    (* Hydrostatic & Ferrostatic Head Balance *)
    rFerrostaticHead_bar            : REAL;     (* Liquid metal ferrostatic pressure at tuyere nozzle level [bar] *)
    rEffectiveBathDepth_m           : REAL;     (* Calculated depth of molten metal bath [m] *)
    rSteelDensity_kgm3              : REAL := 6950.0; (* Liquid austenitic stainless steel density [kg/m3] *)
    rAtmosphericPres_bar            : REAL := 1.013;  (* Ambient barometric pressure [bar] *)
    rAntiWeepingMargin_bar          : REAL := 0.85;   (* Minimum overpressure required to prevent metal ingress [bar] *)

    (* Dynamic Shrouding Aerodynamics *)
    rShroudRatioActual              : REAL;     (* Real-time gas shroud ratio (Q_shroud / Q_core) [dimensionless] *)
    rShroudRatioTarget              : REAL;     (* Dynamic target shroud ratio for thermal veil stability *)
    rTotalCoreFlow_Nm3min           : REAL;     (* Sum of core oxygen and inert gas flow [Nm3/min] *)

    (* Off-gas Decarburization Stoichiometry & Mass Conservation *)
    rCumCarbonLoss_kg               : REAL := 0.0; (* Integrated cumulative carbon mass removed from melt [kg] *)
    rDeltaCarbon_kg                 : REAL;     (* Discrete slice carbon removal per PLC scan cycle [kg] *)
    rOffGasCO_Filtered              : REAL;     (* 1st-order low-pass filtered CO signal [% vol] *)
    rOffGasCO2_Filtered             : REAL;     (* 1st-order low-pass filtered CO2 signal [% vol] *)
    rFilterConstAlpha               : REAL;     (* Digital low-pass filter smoothing coefficient *)
    rMolCarbonPerNm3                : REAL := 0.53587; (* Constant: (12.011 kg/kmol) / (22.414 Nm3/kmol) [kg/Nm3] *)

    (* Discrete-Time State-Space Observer Model (Luenberger / Steady-State Kalman) *)
    (* State vector x_hat = [x1: Remaining Carbon (ppm), x2: Tuyere Tip Temp (deg C), x3: Accretion Thickness (mm)] *)
    aX_hat                          : ARRAY[1..3] OF REAL;
    aX_pred                         : ARRAY[1..3] OF REAL;
    aY_meas                         : ARRAY[1..2] OF REAL; (* [y1: Decarb rate (kg/min), y2: Voted Temp (deg C)] *)
    aY_est                          : ARRAY[1..2] OF REAL;
    aInnov                          : ARRAY[1..2] OF REAL; (* Measurement innovation residual *)

    (* State-Space System Matrices (Discretized at Ts = 0.050s) *)
    aA                              : ARRAY[1..3, 1..3] OF REAL; (* Discrete System Transition Matrix *)
    aB                              : ARRAY[1..3, 1..2] OF REAL; (* Discrete Input Control Matrix *)
    aC                              : ARRAY[1..2, 1..3] OF REAL; (* Measurement Coupling Matrix *)
    aL                              : ARRAY[1..3, 1..2] OF REAL; (* Observer Steady-State Feedback Gain Matrix *)

    (* Refractory Thermal Erosion Accumulator *)
    rRefractoryWearRate_mm_per_min  : REAL;     (* Real-time tuyere wear rate as function of Temp, O2, and Shroud *)

    (* Functional Timers *)
    tonStageTimer                   : TON;      (* Metallurgical dwell timer for blowing stages *)
    tonWeepingGuard                 : TON;      (* Integration timer for underpressure anti-weeping trip *)
    tonOverheatPersistence          : TON;      (* Debounce timer for optical pyrometer over-temperature *)

    (* Internal Scratchpad & Helper Variables *)
    iRow                            : INT;
    iCol                            : INT;
    iKdx                            : INT;
    rDiff12                         : REAL;
    rDiff23                         : REAL;
    rDiff31                         : REAL;
    rMaxAllowedTemp_degC            : REAL := 1740.0; (* Maximum refractory safety limit near tuyere [deg C] *)
    rNominalTuyereDiameter_m        : REAL := 0.024;  (* Nominal tuyere inner pipe diameter [m] *)
    rConverterVesselRadius_m        : REAL := 1.62;   (* Internal hearth radius at tuyere level [m] *)
    bInitialized                    : BOOL := FALSE;  (* First-scan initialization latch flag *)
END_VAR

(*
====================================================================================================
EXECUTION LOGIC STARTS HERE
====================================================================================================
*)

(* === SECTION 1: FIRST SCAN INITIALIZATION OF STATE-SPACE MATRICES === *)
IF NOT bInitialized THEN
    (* Discretized State-Space Transition Matrix A (3x3) *)
    aA[1,1] := 0.99985; aA[1,2] := 0.00000; aA[1,3] := 0.00000;
    aA[2,1] := 0.00005; aA[2,2] := 0.99820; aA[2,3] := -0.01250;
    aA[3,1] := 0.00000; aA[3,2] := -0.00180; aA[3,3] := 0.99910;

    (* Discretized Input Distribution Matrix B (3x2) - [u1: Q_Core_O2, u2: Q_Shroud_Inert] *)
    aB[1,1] := -0.04250; aB[1,2] := 0.00000;
    aB[2,1] :=  0.31500; aB[2,2] := -0.68000;
    aB[3,1] := -0.00850; aB[3,2] :=  0.04500;

    (* Output Coupling Matrix C (2x3) - [y1: dC/dt (kg/min), y2: Voted Temp (deg C)] *)
    aC[1,1] := 0.00192; aC[1,2] := 0.00000; aC[1,3] := 0.00000;
    aC[2,1] := 0.00000; aC[2,2] := 1.00000; aC[2,3] := 0.00000;

    (* Observer Gain Matrix L (3x2) *)
    aL[1,1] := 14.850; aL[1,2] := 0.00000;
    aL[2,1] :=  0.220; aL[2,2] := 0.09500;
    aL[3,1] := -0.018; aL[3,2] := 0.01450;

    (* Seed initial state estimates *)
    IF rBathCarbonInitial_ppm > 100.0 THEN
        aX_hat[1] := rBathCarbonInitial_ppm;
    ELSE
        aX_hat[1] := 18000.0; (* Default to 1.80% C for standard high-carbon hot metal charge *)
    END_IF;
    aX_hat[2] := 1520.0;      (* Initial molten steel charge temperature [deg C] *)
    aX_hat[3] := 5.0;         (* Initial mushroom accretion estimate [mm] *)

    rCumCarbonLoss_kg := 0.0;
    rTuyereRefractoryWear_mm := 0.0;
    bInitialized := TRUE;
END_IF;

(* === SECTION 2: FAILSAFE HARDWARE INTERLOCK & EMERGENCY STOP CHECK === *)
IF (NOT bEStop) OR (NOT bVesselInVerticalBlow) THEN
    bSystemReady := FALSE;
    bEmergencyPurgeActive := TRUE;
    rCoreOxygenFlowSP_Nm3min := 0.0;

    (* If backup nitrogen is available, switch core and shroud to maximum purge cooling *)
    IF bInertGasEmergencyAvailable THEN
        rCoreInertFlowSP_Nm3min := 85.0;
        rShroudInertFlowSP_Nm3min := 22.0;
    ELSE
        rCoreInertFlowSP_Nm3min := 0.0;
        rShroudInertFlowSP_Nm3min := 0.0;
    END_IF;

    wAlarmWord.0 := NOT bEStop;                 (* E-Stop Trip Active *)
    wAlarmWord.1 := NOT bVesselInVerticalBlow;  (* Vessel Not in Vertical Blowing Orientation *)
    wStatusWord := 16#0090;                     (* Emergency State Flag *)
    iBlowState := 90;                           (* Jump immediately to safe purge state *)
END_IF;

(* === SECTION 3: TRIPLE MODULAR REDUNDANT (2oo3) SENSOR VOTING === *)
(* 3.1: 2oo3 Voting for Submerged Pyrometer Channels (deg C) *)
rDiff12 := ABS(rBathTemp_degC_Ch1 - rBathTemp_degC_Ch2);
rDiff23 := ABS(rBathTemp_degC_Ch2 - rBathTemp_degC_Ch3);
rDiff31 := ABS(rBathTemp_degC_Ch3 - rBathTemp_degC_Ch1);

bTempCh1_Fault := (rDiff12 > 45.0) AND (rDiff31 > 45.0);
bTempCh2_Fault := (rDiff12 > 45.0) AND (rDiff23 > 45.0);
bTempCh3_Fault := (rDiff23 > 45.0) AND (rDiff31 > 45.0);

iTempFaultCount := BOOL_TO_INT(bTempCh1_Fault) + BOOL_TO_INT(bTempCh2_Fault) + BOOL_TO_INT(bTempCh3_Fault);

IF iTempFaultCount = 0 THEN
    (* All channels healthy: Compute true median *)
    IF ((rBathTemp_degC_Ch1 >= rBathTemp_degC_Ch2) AND (rBathTemp_degC_Ch1 <= rBathTemp_degC_Ch3)) OR
       ((rBathTemp_degC_Ch1 <= rBathTemp_degC_Ch2) AND (rBathTemp_degC_Ch1 >= rBathTemp_degC_Ch3)) THEN
        rVotedBathTemp_degC := rBathTemp_degC_Ch1;
    ELSIF ((rBathTemp_degC_Ch2 >= rBathTemp_degC_Ch1) AND (rBathTemp_degC_Ch2 <= rBathTemp_degC_Ch3)) OR
          ((rBathTemp_degC_Ch2 <= rBathTemp_degC_Ch1) AND (rBathTemp_degC_Ch2 >= rBathTemp_degC_Ch3)) THEN
        rVotedBathTemp_degC := rBathTemp_degC_Ch2;
    ELSE
        rVotedBathTemp_degC := rBathTemp_degC_Ch3;
    END_IF;
ELSIF iTempFaultCount = 1 THEN
    (* 1 Channel Failed: Graceful degradation to 1oo2 average of surviving healthy channels *)
    IF bTempCh1_Fault THEN
        rVotedBathTemp_degC := (rBathTemp_degC_Ch2 + rBathTemp_degC_Ch3) * 0.5;
    ELSIF bTempCh2_Fault THEN
        rVotedBathTemp_degC := (rBathTemp_degC_Ch1 + rBathTemp_degC_Ch3) * 0.5;
    ELSE
        rVotedBathTemp_degC := (rBathTemp_degC_Ch1 + rBathTemp_degC_Ch2) * 0.5;
    END_IF;
    wAlarmWord.5 := TRUE; (* TMR Temperature Sensor Discrepancy Degraded to 1oo2 *)
ELSE
    (* Multiple failures: Sensor redundancy lost *)
    rVotedBathTemp_degC := aX_hat[2]; (* Fallback to observer predicted internal temperature *)
    wAlarmWord.6 := TRUE; (* TMR Temperature Redundancy Lost *)
END_IF;

(* 3.2: 2oo3 Voting for Core Pressure Transmitters (bar) *)
rDiff12 := ABS(rCorePres_bar_PT1 - rCorePres_bar_PT2);
rDiff23 := ABS(rCorePres_bar_PT2 - rCorePres_bar_PT3);
rDiff31 := ABS(rCorePres_bar_PT3 - rCorePres_bar_PT1);

bPresPT1_Fault := (rDiff12 > 0.65) AND (rDiff31 > 0.65);
bPresPT2_Fault := (rDiff12 > 0.65) AND (rDiff23 > 0.65);
bPresPT3_Fault := (rDiff23 > 0.65) AND (rDiff31 > 0.65);

iPresFaultCount := BOOL_TO_INT(bPresPT1_Fault) + BOOL_TO_INT(bPresPT2_Fault) + BOOL_TO_INT(bPresPT3_Fault);

IF iPresFaultCount = 0 THEN
    IF ((rCorePres_bar_PT1 >= rCorePres_bar_PT2) AND (rCorePres_bar_PT1 <= rCorePres_bar_PT3)) OR
       ((rCorePres_bar_PT1 <= rCorePres_bar_PT2) AND (rCorePres_bar_PT1 >= rCorePres_bar_PT3)) THEN
        rVotedCorePres_bar := rCorePres_bar_PT1;
    ELSIF ((rCorePres_bar_PT2 >= rCorePres_bar_PT1) AND (rCorePres_bar_PT2 <= rCorePres_bar_PT3)) OR
          ((rCorePres_bar_PT2 <= rCorePres_bar_PT1) AND (rCorePres_bar_PT2 >= rCorePres_bar_PT3)) THEN
        rVotedCorePres_bar := rCorePres_bar_PT2;
    ELSE
        rVotedCorePres_bar := rCorePres_bar_PT3;
    END_IF;
ELSIF iPresFaultCount = 1 THEN
    IF bPresPT1_Fault THEN
        rVotedCorePres_bar := (rCorePres_bar_PT2 + rCorePres_bar_PT3) * 0.5;
    ELSIF bPresPT2_Fault THEN
        rVotedCorePres_bar := (rCorePres_bar_PT1 + rCorePres_bar_PT3) * 0.5;
    ELSE
        rVotedCorePres_bar := (rCorePres_bar_PT1 + rCorePres_bar_PT2) * 0.5;
    END_IF;
    wAlarmWord.7 := TRUE; (* TMR Pressure Transmitter Degraded *)
ELSE
    rVotedCorePres_bar := rTuyereShroudSupplyPres_bar; (* Severe fallback *)
    wAlarmWord.8 := TRUE; (* TMR Pressure Redundancy Lost *)
END_IF;

(* === SECTION 4: HYDRODYNAMIC FERROSTATIC BALANCE & ANTI-WEEPING INTERLOCK === *)
(* Calculate bath depth based on tonnage and cylindrical geometry approximation: V = mass / rho *)
IF rMeltMass_ton > 10.0 THEN
    rEffectiveBathDepth_m := (rMeltMass_ton * 1000.0) / (rSteelDensity_kgm3 * 3.141592 * rConverterVesselRadius_m * rConverterVesselRadius_m);
ELSE
    rEffectiveBathDepth_m := 1.85; (* Conservative fallback depth [m] *)
END_IF;

(* Liquid steel ferrostatic head: P_ferro = rho * g * h / 10^5 + P_atm [bar] *)
rFerrostaticHead_bar := ((rSteelDensity_kgm3 * 9.80665 * rEffectiveBathDepth_m) / 100000.0) + rAtmosphericPres_bar;

(* Anti-Weeping Protection: Core backpressure must exceed ferrostatic head by safe margin *)
tonWeepingGuard(IN := (rVotedCorePres_bar < (rFerrostaticHead_bar + rAntiWeepingMargin_bar)) AND (iBlowState >= 10) AND (iBlowState <= 40),
                PT := T#120MS);

IF tonWeepingGuard.Q THEN
    bEmergencyPurgeActive := TRUE;
    wAlarmWord.2 := TRUE; (* Critical Anti-Weeping Low Pressure Interlock Activated *)
    iBlowState := 90;     (* Force Emergency Inert Gas Flush *)
END_IF;

(* Tuyere Tip Refractory Overheat Protection Check *)
tonOverheatPersistence(IN := (rVotedBathTemp_degC > rMaxAllowedTemp_degC), PT := T#500MS);
bTuyereOverheatAlarm := tonOverheatPersistence.Q;
IF bTuyereOverheatAlarm THEN
    wAlarmWord.3 := TRUE; (* Refractory Critical Overheat Alarm *)
END_IF;

(* === SECTION 5: OFF-GAS DECARBURIZATION STOICHIOMETRIC RATE === *)
(* Digital 1st-order low-pass filter on off-gas analyzer signals to eliminate duct turbulence noise *)
rFilterConstAlpha := LIMIT(0.01, (rCycleTime_s / (0.65 + rCycleTime_s)), 1.0);
rOffGasCO_Filtered  := rOffGasCO_Filtered  + rFilterConstAlpha * (rOffGasCO_pct  - rOffGasCO_Filtered);
rOffGasCO2_Filtered := rOffGasCO2_Filtered + rFilterConstAlpha * (rOffGasCO2_pct - rOffGasCO2_Filtered);

(* Decarburization rate: dC/dt = (M_C / V_mol) * Q_offgas * (CO% + CO2%) * 10^-2 [kg/min] *)
IF rOffGasFlow_Nm3min > 1.0 THEN
    rInstantDecarbRate_kgmin := rMolCarbonPerNm3 * rOffGasFlow_Nm3min * ((rOffGasCO_Filtered + rOffGasCO2_Filtered) / 100.0);
ELSE
    rInstantDecarbRate_kgmin := 0.0;
END_IF;

(* Carbon removal mass integration over discrete scan slice *)
rDeltaCarbon_kg := rInstantDecarbRate_kgmin * (rCycleTime_s / 60.0);
rCumCarbonLoss_kg := rCumCarbonLoss_kg + rDeltaCarbon_kg;

(* === SECTION 6: STATE-SPACE OBSERVER ESTIMATION (KALMAN / LUENBERGER) === *)
(* 6.1: Define measurement vector y_meas *)
aY_meas[1] := rInstantDecarbRate_kgmin;
aY_meas[2] := rVotedBathTemp_degC;

(* 6.2: State prediction step: x_pred = A * x_hat + B * u *)
FOR iRow := 1 TO 3 DO
    aX_pred[iRow] := 0.0;
    FOR iCol := 1 TO 3 DO
        aX_pred[iRow] := aX_pred[iRow] + (aA[iRow, iCol] * aX_hat[iCol]);
    END_FOR;
    aX_pred[iRow] := aX_pred[iRow] + (aB[iRow, 1] * rCoreOxygenFlowSP_Nm3min) + (aB[iRow, 2] * rShroudInertFlowSP_Nm3min);
END_FOR;

(* 6.3: Estimated measurement calculation: y_est = C * x_pred *)
FOR iRow := 1 TO 2 DO
    aY_est[iRow] := 0.0;
    FOR iCol := 1 TO 3 DO
        aY_est[iRow] := aY_est[iRow] + (aC[iRow, iCol] * aX_pred[iCol]);
    END_FOR;
    (* Innovation residual vector: innov = y_meas - y_est *)
    aInnov[iRow] := aY_meas[iRow] - aY_est[iRow];
END_FOR;

(* 6.4: State correction step: x_hat = x_pred + L * innov *)
FOR iRow := 1 TO 3 DO
    aX_hat[iRow] := aX_pred[iRow];
    FOR iKdx := 1 TO 2 DO
        aX_hat[iRow] := aX_hat[iRow] + (aL[iRow, iKdx] * aInnov[iKdx]);
    END_FOR;
END_FOR;

(* Clamp dissolved carbon state estimate to realistic metallurgical boundaries *)
aX_hat[1] := LIMIT(50.0, aX_hat[1], 45000.0);
rEstBathCarbon_ppm := aX_hat[1];
rMushroomThickness_mm := aX_hat[3];

(* === SECTION 7: MULTI-STAGE METALLURGICAL BLOWING SEQUENCER === *)
CASE iBlowState OF
    0: (* STANDBY / PURGE CHECK *)
        bSystemReady := bEnable AND bEStop AND bVesselInVerticalBlow AND (iPresFaultCount < 2) AND (iTempFaultCount < 2);
        bEmergencyPurgeActive := FALSE;
        rCoreOxygenFlowSP_Nm3min := 0.0;
        rCoreInertFlowSP_Nm3min := 15.0;     (* Low holding purge to prevent nozzle plugging *)
        rShroudInertFlowSP_Nm3min := 5.0;    (* Annular holding purge *)
        rShroudRatioTarget := 0.15;
        wStatusWord := 16#0001;              (* Standby Status *)

        IF bSystemReady AND bEnable THEN
            tonStageTimer(IN := FALSE, PT := T#1S);
            iBlowState := 10;                (* Advance to Stage 1 Decarburization *)
        END_IF;

    10: (* STAGE 1: HIGH CARBON DECARBURIZATION (O2:Inert = 4:1) *)
        (* High carbon activity: Maximum oxygen efficiency without substantial Cr oxidation *)
        wStatusWord := 16#0002;
        rCoreOxygenFlowSP_Nm3min := 110.0;   (* [Nm3/min] *)
        rCoreInertFlowSP_Nm3min  := 27.5;    (* [Nm3/min] (Ar or N2) *)
        rShroudRatioTarget := 0.14;          (* Dynamic shroud ratio 14% *)
        rShroudInertFlowSP_Nm3min := (rCoreOxygenFlowSP_Nm3min + rCoreInertFlowSP_Nm3min) * rShroudRatioTarget;

        (* Transition condition: Bath carbon drops below 4000 ppm (0.40% C) *)
        IF (rEstBathCarbon_ppm <= 4000.0) THEN
            tonStageTimer(IN := FALSE, PT := T#1S);
            iBlowState := 20;                (* Advance to Stage 2 *)
        END_IF;

    20: (* STAGE 2: MEDIUM CARBON DECARBURIZATION (O2:Inert = 2:1) *)
        (* Dilution regime begins: Inert gas lowers P_CO to preserve chromium *)
        wStatusWord := 16#0004;
        rCoreOxygenFlowSP_Nm3min := 80.0;    (* [Nm3/min] *)
        rCoreInertFlowSP_Nm3min  := 40.0;    (* [Nm3/min] *)
        rShroudRatioTarget := 0.18;          (* Increased shroud cooling as core gas shifts *)
        rShroudInertFlowSP_Nm3min := (rCoreOxygenFlowSP_Nm3min + rCoreInertFlowSP_Nm3min) * rShroudRatioTarget;

        (* Transition condition: Bath carbon drops below 1200 ppm (0.12% C) *)
        IF (rEstBathCarbon_ppm <= 1200.0) THEN
            tonStageTimer(IN := FALSE, PT := T#1S);
            iBlowState := 30;                (* Advance to Stage 3 *)
        END_IF;

    30: (* STAGE 3: LOW CARBON DECARBURIZATION (O2:Inert = 1:3) *)
        (* Deep decarburization: Pure argon dilution to strip carbon while minimizing Cr2O3 formation *)
        wStatusWord := 16#0008;
        rCoreOxygenFlowSP_Nm3min := 25.0;    (* [Nm3/min] *)
        rCoreInertFlowSP_Nm3min  := 75.0;    (* [Nm3/min] (Pure Argon) *)
        rShroudRatioTarget := 0.22;          (* High shroud protective veil to prevent hot spot refractory burn *)
        rShroudInertFlowSP_Nm3min := (rCoreOxygenFlowSP_Nm3min + rCoreInertFlowSP_Nm3min) * rShroudRatioTarget;

        (* Transition condition: Aim carbon reached *)
        IF (rEstBathCarbon_ppm <= rCarbonTarget_ppm) THEN
            tonStageTimer(IN := FALSE, PT := T#180S); (* Initialize 3-minute reduction timer *)
            iBlowState := 40;                (* Advance to Slag Reduction Phase *)
        END_IF;

    40: (* STAGE 4: REDUCTION & DESULFURIZATION STIRRING *)
        (* Silicon additions recover oxidized chromium from slag: 2 Cr2O3 + 3 Si -> 4 Cr + 3 SiO2 *)
        wStatusWord := 16#0010;
        rCoreOxygenFlowSP_Nm3min := 0.0;     (* Oxygen strictly zeroed *)
        rCoreInertFlowSP_Nm3min  := 55.0;    (* Strong stirring argon plume for slag-metal contact *)
        rShroudRatioTarget := 0.16;
        rShroudInertFlowSP_Nm3min := rCoreInertFlowSP_Nm3min * rShroudRatioTarget;

        tonStageTimer(IN := TRUE, PT := T#180S);
        IF tonStageTimer.Q THEN
            tonStageTimer(IN := FALSE, PT := T#1S);
            iBlowState := 50;                (* Blow sequence complete *)
        END_IF;

    50: (* BLOW SEQUENCE COMPLETE / HOLDING *)
        wStatusWord := 16#0020;
        rCoreOxygenFlowSP_Nm3min := 0.0;
        rCoreInertFlowSP_Nm3min  := 20.0;    (* Tuyere anti-plugging holding flow *)
        rShroudInertFlowSP_Nm3min := 6.0;
        bSystemReady := TRUE;

        IF NOT bEnable THEN
            iBlowState := 0;                 (* Return to Standby *)
        END_IF;

    90: (* EMERGENCY HIGH-PRESSURE PURGE *)
        wStatusWord := 16#0080;
        bEmergencyPurgeActive := TRUE;
        rCoreOxygenFlowSP_Nm3min := 0.0;     (* Lock out oxygen instantly *)

        IF bInertGasEmergencyAvailable THEN
            rCoreInertFlowSP_Nm3min := 120.0;  (* Maximum emergency inert blast *)
            rShroudInertFlowSP_Nm3min := 28.0; (* Annular support blast *)
        ELSE
            rCoreInertFlowSP_Nm3min := 50.0;
            rShroudInertFlowSP_Nm3min := 15.0;
        END_IF;

        (* Latch until manual acknowledge and safety conditions restored *)
        IF bAcknowledgeFault AND bEStop AND bVesselInVerticalBlow AND (rVotedCorePres_bar >= rFerrostaticHead_bar) THEN
            wAlarmWord := 16#0000;
            bEmergencyPurgeActive := FALSE;
            iBlowState := 0;
        END_IF;

    99: (* CRITICAL FAULT LOCKOUT *)
        wStatusWord := 16#00FF;
        rCoreOxygenFlowSP_Nm3min := 0.0;
        rCoreInertFlowSP_Nm3min := 25.0;
        rShroudInertFlowSP_Nm3min := 8.0;
        bSystemReady := FALSE;

        IF bAcknowledgeFault AND bEStop THEN
            wAlarmWord := 16#0000;
            iBlowState := 0;
        END_IF;

    ELSE
        iBlowState := 99; (* Invalid state handler *)
END_CASE;

(* === SECTION 8: SHROUD RATIO VERIFICATION & ADAPTIVE COMPENSATION === *)
rTotalCoreFlow_Nm3min := rCoreOxygenFlowSP_Nm3min + rCoreInertFlowSP_Nm3min;
IF rTotalCoreFlow_Nm3min > 1.0 THEN
    rShroudRatioActual := rShroudInertFlowSP_Nm3min / rTotalCoreFlow_Nm3min;
ELSE
    rShroudRatioActual := 0.0;
END_IF;

(* Annular shroud ratio fault detection *)
IF (iBlowState >= 10) AND (iBlowState <= 30) THEN
    IF (rShroudRatioActual < 0.10) OR (rShroudRatioActual > 0.32) THEN
        wAlarmWord.4 := TRUE; (* Shroud Flow Ratio Out of Aerodynamic Envelope *)
    END_IF;
END_IF;

(* === SECTION 9: CUMULATIVE TUYERE REFRACTORY WEAR ACCUMULATOR === *)
(*
  Refractory wear rate model [mm/min]:
  Governed by: (1) Thermal stress above 1680 C, (2) Direct O2 chemical attack,
  and (3) Thermal barrier insufficiency if shroud ratio falls below target.
*)
IF (rVotedBathTemp_degC > 1680.0) THEN
    rRefractoryWearRate_mm_per_min := 0.0045 * (rVotedBathTemp_degC - 1680.0);
ELSE
    rRefractoryWearRate_mm_per_min := 0.015; (* Baseline erosive wash rate *)
END_IF;

(* Add oxygen flux combustion penalty *)
rRefractoryWearRate_mm_per_min := rRefractoryWearRate_mm_per_min + (0.025 * (rCoreOxygenFlowSP_Nm3min / 100.0));

(* Add shroud deficit multiplier *)
IF (rShroudRatioActual < rShroudRatioTarget) AND (rShroudRatioTarget > 0.01) THEN
    rRefractoryWearRate_mm_per_min := rRefractoryWearRate_mm_per_min * (1.0 + 3.0 * (rShroudRatioTarget - rShroudRatioActual));
END_IF;

(* Euler accumulation of physical refractory wall thinning *)
rTuyereRefractoryWear_mm := rTuyereRefractoryWear_mm + (rRefractoryWearRate_mm_per_min * (rCycleTime_s / 60.0));

IF rTuyereRefractoryWear_mm > 350.0 THEN
    wAlarmWord.9 := TRUE; (* Tuyere Refractory Critical Wear Limit Exceeded *)
END_IF;

